#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    const long long INF = (1LL << 60);
    vector<long long> h(N);

    for (int i = 0; i < N; ++i) {
        cin >> h[i];
        if (h[i] == -1) h[i] = INF;
    }

    for (int i = 1; i < N; ++i)
        h[i] = min(h[i], h[i - 1] + 1);

    for (int i = N - 2; i >= 0; --i)
        h[i] = min(h[i], h[i + 1] + 1);

    for (int i = 0; i < N; ++i) {
        if (i) cout << ' ';
        cout << h[i];
    }
    cout << '\n';

    return 0;
}
